<?php namespace App\Models; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\Relations\HasMany; class Opportunity extends Model { protected $guarded=[]; protected function casts():array{return ['expected_decision_at'=>'date','archived_at'=>'datetime'];} public function assessments():HasMany{return $this->hasMany(InitialAssessment::class);} public function proposals():HasMany{return $this->hasMany(Proposal::class);} public function negotiations():HasMany{return $this->hasMany(NegotiationEntry::class);} }
